<script setup lang="ts">
import { onMounted, ref } from "vue"; import { http } from "../api";
const inventory=ref<any[]>([]), sales=ref<any[]>([]), purchases=ref<any[]>([]); onMounted(async()=>{const data=await Promise.all([http.get("/stock"),http.get("/orders/sales"),http.get("/orders/purchases")]);inventory.value=data[0] as unknown as any[];sales.value=data[1] as unknown as any[];purchases.value=data[2] as unknown as any[]});
function exportCsv(){const rows=[["零件编号","零件名称","库存","平均成本"],...inventory.value.map(x=>[x.part_number,x.name,x.quantity,x.avg_cost])];const blob=new Blob(["\ufeff"+rows.map(x=>x.join(",")).join("\n")],{type:"text/csv"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="库存报表.csv";a.click();URL.revokeObjectURL(a.href)}
</script>
<template><div class="page-actions"><span>进销存汇总</span><el-button type="primary" @click="exportCsv">导出库存 CSV</el-button></div><div class="metrics report"><div><span>采购单数</span><strong>{{purchases.length}}</strong></div><div><span>销售单数</span><strong>{{sales.length}}</strong></div><div><span>库存品种</span><strong>{{inventory.length}}</strong></div><div><span>库存金额</span><strong>¥ {{(inventory.reduce((n,x)=>n+x.stock_amount,0)/100).toFixed(2)}}</strong></div></div><div class="panel"><el-table :data="inventory"><el-table-column prop="part_number" label="编号"/><el-table-column prop="name" label="名称"/><el-table-column prop="quantity" label="期末库存"/><el-table-column prop="avg_cost" label="平均成本(分)"/><el-table-column prop="stock_amount" label="库存金额(分)"/></el-table></div></template>
<style scoped>.report{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:18px}.report>div{background:#fff;border:1px solid #e2e7ef;padding:18px;border-radius:8px}.report span,.report strong{display:block}.report span{color:#657186;margin-bottom:12px}.report strong{font-size:24px}</style>
